CREATE TYPE "typ_medium" AS ENUM (
	'ksiazka',
	'film',
	'serial',
	'muzyka',
	'gra'
);

CREATE TYPE "typ_status" AS ENUM (
	'zaczete',
	'ukonczone',
	'porzucone'
);

CREATE TABLE IF NOT EXISTS "dzielo" (
	"id_dziela" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"tytul" VARCHAR(255),
	"orginalny_tytul" VARCHAR(255),
	"typ_medium" TYP_MEDIUM,
	"data_wydania" DATE,
	"opis" VARCHAR(255),
	"tagline" VARCHAR(255),
	PRIMARY KEY("id_dziela")
);

CREATE TABLE IF NOT EXISTS "dzielo_ksiazka" (
	"id_medium" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"liczba_stron" INTEGER,
	"ISBN" VARCHAR(255),
	"id_autora" INTEGER,
	"nr_tomu" INTEGER,
	PRIMARY KEY("id_medium")
) INHERITS ("dzielo");

CREATE TABLE IF NOT EXISTS "dzielo_film" (
	"id_medium" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"czas_trwania" INTEGER,
	PRIMARY KEY("id_medium")
) INHERITS ("dzielo");

CREATE TABLE IF NOT EXISTS "dzielo_gra" (
	"id_medium" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_platformy" INTEGER,
	PRIMARY KEY("id_medium")
) INHERITS ("dzielo");

CREATE TABLE IF NOT EXISTS "platforma" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nazwa_platformy" VARCHAR(255),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "gatunek" (
	"id" INTEGER,
	"nazwa_gatunku" VARCHAR(255),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "dzielo_gatunek" (
	"id_medium" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_gatunku" INTEGER,
	PRIMARY KEY("id_medium", "id_gatunku")
);

CREATE TABLE IF NOT EXISTS "osoba" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"imie" VARCHAR(255),
	"nazwisko" VARCHAR(255),
	"kraj_pochodzenia" VARCHAR(255),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "dzielo_osoba" (
	"id_medium" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_osoby" INTEGER,
	PRIMARY KEY("id_medium", "id_osoby")
);

CREATE TABLE IF NOT EXISTS "dzielo_serial" (
	"id_medium" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"liczba_sezonow" INTEGER,
	PRIMARY KEY("id_medium")
);

CREATE TABLE IF NOT EXISTS "sezon" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_medium" INTEGER,
	"numer_sezonu" INTEGER,
	"tytul_sezonu" VARCHAR(255),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "odcinek" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_sezonu" INTEGER,
	"numer_odcinka" INTEGER,
	"tytul_odcinka" VARCHAR(255),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "uzytkownik" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nazwa" VARCHAR(255),
	"email" VARCHAR(255),
	"haslo" VARCHAR(255),
	"imie" VARCHAR(255),
	"kraj" VARCHAR(255),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "biblioteka_uzytkownika" (
	"id_wpisu" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_uzytkownika" INTEGER,
	"id_medium" INTEGER,
	"status" TYP_STATUS,
	"ocena" INTEGER,
	"recenzja_tekstowa" VARCHAR(255),
	"data_dodania" DATE,
	"data_rozpoczecia" DATE,
	"data_zakonczenia" DATE,
	"progres" INTEGER,
	PRIMARY KEY("id_wpisu")
);

CREATE TABLE IF NOT EXISTS "seria" (
	"id_serii" INTEGER NOT NULL,
	"nazwa_serii" VARCHAR(255) NOT NULL,
	"typ_serii" VARCHAR(255),
	PRIMARY KEY("id_serii")
);

CREATE TABLE IF NOT EXISTS "dzielo_seri" (
	"id_serii" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_medium" INTEGER,
	"numer_w_serii" VARCHAR(255),
	PRIMARY KEY("id_serii", "id_medium")
);

CREATE TABLE IF NOT EXISTS "franczyza" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nazwa" VARCHAR(255),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "dzielo_franczyza" (
	"id_franczyzy" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_serii" INTEGER,
	PRIMARY KEY("id_franczyzy", "id_serii")
);

ALTER TABLE "platforma"
ADD FOREIGN KEY("id") REFERENCES "dzielo_gra"("id_medium")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "dzielo"
ADD FOREIGN KEY("id_dziela") REFERENCES "dzielo_gra"("id_medium")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "dzielo_ksiazka"
ADD FOREIGN KEY("id_medium") REFERENCES "dzielo"("id_dziela")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "dzielo"
ADD FOREIGN KEY("id_dziela") REFERENCES "dzielo_film"("id_medium")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "gatunek"
ADD FOREIGN KEY("id") REFERENCES "dzielo_gatunek"("id_gatunku")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "osoba"
ADD FOREIGN KEY("id") REFERENCES "dzielo_osoba"("id_osoby")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "dzielo"
ADD FOREIGN KEY("id_dziela") REFERENCES "dzielo_serial"("id_medium")
